import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CZqXuAiL.js";const u=JSON.parse('{"title":"Rule Types","description":"All 13 Firewall-Plus iptables rule types — what each one does, when to use it, and how scopes work.","frontmatter":{"title":"Rule Types","description":"All 13 Firewall-Plus iptables rule types — what each one does, when to use it, and how scopes work."},"headers":[],"relativePath":"firewall-plus/fwp-aside/user-guide/rules.md","filePath":"firewall-plus/fwp-aside/user-guide/rules.md","lastUpdated":null}'),r={name:"firewall-plus/fwp-aside/user-guide/rules.md"};function o(n,e,l,d,p,h){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="rule-types" tabindex="-1">Rule Types <a class="header-anchor" href="#rule-types" aria-label="Permalink to &quot;Rule Types&quot;">​</a></h1><p>Firewall-Plus supports <strong>13 rule types</strong>. Each rule is scoped either <strong>per-port</strong> (rendered into a <code>FWP-{serverId}-{port}</code> chain jumped to from INPUT with <code>--dport</code>) or <strong>globally</strong> for the server (<code>FWP-{serverId}</code> chain, multiport across allocations). All rules are comment-tagged for idempotency and applied atomically.</p><p>Admin-set limits (max rules per server, max rates) are enforced on save by the panel&#39;s LimitChecker.</p><hr><h2 id="rate-volume-limits" tabindex="-1">Rate &amp; Volume Limits <a class="header-anchor" href="#rate-volume-limits" aria-label="Permalink to &quot;Rate &amp; Volume Limits&quot;">​</a></h2><h3 id="syn-limit" tabindex="-1"><code>syn_limit</code> <a class="header-anchor" href="#syn-limit" aria-label="Permalink to &quot;`syn_limit`&quot;">​</a></h3><p>Limits the rate of inbound TCP SYN packets (new connection attempts). The primary defense against SYN floods; uses hashlimit-style matching per scope.</p><h3 id="tcp-limit" tabindex="-1"><code>tcp_limit</code> <a class="header-anchor" href="#tcp-limit" aria-label="Permalink to &quot;`tcp_limit`&quot;">​</a></h3><p>General TCP packet rate limit for the scope — caps total TCP packets/sec regardless of flags.</p><h3 id="udp-limit" tabindex="-1"><code>udp_limit</code> <a class="header-anchor" href="#udp-limit" aria-label="Permalink to &quot;`udp_limit`&quot;">​</a></h3><p>UDP packet rate limit. The bread-and-butter rule for game servers, since most game traffic (and most L4 floods against them) is UDP.</p><h3 id="connection-limit" tabindex="-1"><code>connection_limit</code> <a class="header-anchor" href="#connection-limit" aria-label="Permalink to &quot;`connection_limit`&quot;">​</a></h3><p>Caps the number of <strong>concurrent connections</strong> (per source or per scope, depending on configuration). Stops connection-exhaustion attacks that stay under packet-rate thresholds.</p><h3 id="global-packet-limit" tabindex="-1"><code>global_packet_limit</code> <a class="header-anchor" href="#global-packet-limit" aria-label="Permalink to &quot;`global_packet_limit`&quot;">​</a></h3><p>A single packet/sec ceiling across the whole server, independent of protocol. Use as a coarse backstop behind the more specific limits.</p><h3 id="new-connection-rate" tabindex="-1"><code>new_connection_rate</code> <a class="header-anchor" href="#new-connection-rate" aria-label="Permalink to &quot;`new_connection_rate`&quot;">​</a></h3><p>Limits how fast <strong>new</strong> connections may be established (state NEW), distinct from total packet rate. Slows down botnet connect floods and rapid reconnect abuse.</p><h3 id="burst-protection" tabindex="-1"><code>burst_protection</code> <a class="header-anchor" href="#burst-protection" aria-label="Permalink to &quot;`burst_protection`&quot;">​</a></h3><p>An <strong>alias</strong> that maps onto the SYN limit engine with burst-oriented parameters — absorbs short legitimate bursts (map downloads, lobby joins) while still capping sustained SYN rates. Configuring it writes a syn-limit-style rule.</p><h2 id="packet-hygiene" tabindex="-1">Packet Hygiene <a class="header-anchor" href="#packet-hygiene" aria-label="Permalink to &quot;Packet Hygiene&quot;">​</a></h2><h3 id="fragmented-drop" tabindex="-1"><code>fragmented_drop</code> <a class="header-anchor" href="#fragmented-drop" aria-label="Permalink to &quot;`fragmented_drop`&quot;">​</a></h3><p>Drops fragmented packets. Legitimate game traffic virtually never fragments; floods use fragments to bypass per-packet inspection and chew reassembly CPU. Safe and recommended for most game servers.</p><h3 id="ttl-filter" tabindex="-1"><code>ttl_filter</code> <a class="header-anchor" href="#ttl-filter" aria-label="Permalink to &quot;`ttl_filter`&quot;">​</a></h3><p>Filters packets by TTL value — drops packets whose TTL is implausibly low/high for real clients. Catches some spoofed and amplified traffic patterns.</p><h3 id="packet-size-filter" tabindex="-1"><code>packet_size_filter</code> <a class="header-anchor" href="#packet-size-filter" aria-label="Permalink to &quot;`packet_size_filter`&quot;">​</a></h3><p>Drops packets outside a configured size range (min/max bytes). Game protocols have well-known packet sizes; floods are often tiny (or jumbo). Size filtering is cheap and surprisingly effective.</p><h3 id="stateful-tracking" tabindex="-1"><code>stateful_tracking</code> <a class="header-anchor" href="#stateful-tracking" aria-label="Permalink to &quot;`stateful_tracking`&quot;">​</a></h3><p>Enables conntrack-based stateful matching: established/related traffic is accepted fast-path, and invalid-state packets are dropped. The foundation rule — enable it first, then layer limits on top.</p><h2 id="advanced" tabindex="-1">Advanced <a class="header-anchor" href="#advanced" aria-label="Permalink to &quot;Advanced&quot;">​</a></h2><h3 id="geo-filter" tabindex="-1"><code>geo_filter</code> <a class="header-anchor" href="#geo-filter" aria-label="Permalink to &quot;`geo_filter`&quot;">​</a></h3><p>Filters traffic by source country using a MaxMind GeoLite2 database on the node.</p><div class="warning custom-block"><p class="custom-block-title">Requires a GeoIP database</p><p>The node must have <code>geoipDbPath</code> set in <code>/etc/firewall-plus/config.json</code> pointing at a valid <code>.mmdb</code> you downloaded yourself (GeoLite2 is licensed and not redistributed). Enabling <code>geo_filter</code> without a DB is <strong>rejected</strong> — it fails loudly rather than silently passing traffic. Admin → Nodes shows GeoIP availability from the last health check, and the client Geo IP tab only appears when the node reports it available.</p></div><h3 id="connection-timeout" tabindex="-1"><code>connection_timeout</code> <a class="header-anchor" href="#connection-timeout" aria-label="Permalink to &quot;`connection_timeout`&quot;">​</a></h3><p><strong>Legacy no-op.</strong> Still accepted by the API so old database rows don&#39;t error, but the node intentionally emits <strong>no iptables rules</strong> for it and the panel UI no longer offers it. Existing rows are harmless; delete them at your convenience.</p><hr><h2 id="scopes-per-port-vs-global" tabindex="-1">Scopes: per-port vs global <a class="header-anchor" href="#scopes-per-port-vs-global" aria-label="Permalink to &quot;Scopes: per-port vs global&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Chain</th><th>Matches</th></tr></thead><tbody><tr><td>Per-port</td><td><code>FWP-{serverId}-{port}</code></td><td>One allocation port, <code>--dport</code> jump from INPUT (tcp + udp)</td></tr><tr><td>Global</td><td><code>FWP-{serverId}</code></td><td>All of the server&#39;s allocations (multiport, with <code>-p</code>)</td></tr></tbody></table><p>Prefer <strong>per-port</strong> rules when a server has several allocations and only one faces the public (e.g. a game port vs. a query port). Use <strong>global</strong> rules for server-wide hygiene like <code>stateful_tracking</code> and <code>fragmented_drop</code>.</p><h2 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h2><p>The <strong>Presets</strong> tab ships system game presets (curated rule sets per game) and lets users save their own. Applying a preset creates its rules in one shot; nothing is pushed to the node until you click <strong>Apply firewall</strong>. Admins manage the system catalog from <strong>Admin → Firewall → Presets</strong>.</p><h2 id="verify-rendered-rules-node-root" tabindex="-1">Verify rendered rules (node, root) <a class="header-anchor" href="#verify-rendered-rules-node-root" aria-label="Permalink to &quot;Verify rendered rules (node, root)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FWP-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">serverI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FWP-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">serverI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">por</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fwp-wl-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">serverI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span></code></pre></div><p>Duplicate rules are skipped automatically (comment-tagged idempotency), so re-applying is always safe.</p>',43)])])}const k=t(r,[["render",o]]);export{u as __pageData,k as default};
